-- SYNTHETIC ONLY. Invented IDs, merchant/person, values and dates. NOT EXECUTED.
-- Run only in a fresh isolated disposable PostgreSQL 17 database, after coordinator approval.
BEGIN;
DO $guard$ BEGIN
 IF current_setting('server_version_num')::int NOT BETWEEN 170000 AND 179999 THEN RAISE EXCEPTION 'PG17 required'; END IF;
 IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','v','m','p','f')) OR to_regnamespace('lts_q26_private') IS NOT NULL THEN RAISE EXCEPTION 'empty disposable database required'; END IF;
END $guard$;
CREATE TABLE public.lts_open_finance_staging(id uuid PRIMARY KEY,user_id uuid,resource_type text,provider_deleted_at timestamptz,raw_hash text,raw_payload jsonb,normalized_payload jsonb,posting_date date,signed_amount numeric,currency text,provider text,institution_code text,provider_record_id text,provider_account_ref text);
CREATE TABLE public.fixture_test_log(label text PRIMARY KEY);
CREATE FUNCTION public.fixture_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $f$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'fixture failed: %',label; END IF; INSERT INTO public.fixture_test_log VALUES(label); END $f$;
CREATE TABLE public.fixture_expenses(row_key text,event_date date,transaction_date date,competence_month date,amount numeric,category text,beneficiary text,description text,account_source text,source_table text,source_ref text,coverage_mode text,raw_category text,raw_reference text,purchase_date date,identity_status text,management_group text,management_subgroup text,property_code text,property_component text);
CREATE TABLE public.fixture_other_expenses(LIKE public.fixture_expenses);
CREATE SCHEMA lts_q26_private AUTHORIZATION postgres;
REVOKE ALL ON SCHEMA lts_q26_private FROM PUBLIC;
CREATE TABLE lts_q26_private.nominal_pair (
 operation_id uuid PRIMARY KEY CHECK(operation_id='55555555-5555-4555-8555-555555555555'::uuid),
 user_id uuid NOT NULL CHECK(user_id='11111111-1111-4111-8111-111111111111'::uuid),
 representative_id uuid NOT NULL CHECK(representative_id='22222222-2222-4222-8222-222222222222'::uuid),
 prior_id uuid NOT NULL CHECK(prior_id='33333333-3333-4333-8333-333333333333'::uuid),
 competence_month date NOT NULL CHECK(competence_month=date '2020-10-01'),
 amount numeric(14,2) NOT NULL CHECK(amount=12.34), currency text NOT NULL CHECK(currency='BRL'),
 family text NOT NULL CHECK(family='aeternum'),
 representative_expected jsonb NOT NULL, prior_expected jsonb NOT NULL, invoice_expected jsonb NOT NULL,
 representative_expense_mask jsonb NOT NULL, prior_expense_mask jsonb NOT NULL,
 approval jsonb NOT NULL, decision_lineage jsonb NOT NULL,
 active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 revoked_at timestamptz, revoked_reason text,
 CHECK(representative_id<>prior_id), CHECK(active=(revoked_at IS NULL)),
 UNIQUE(user_id,prior_id,competence_month), UNIQUE(user_id,representative_id,competence_month)
);
ALTER TABLE lts_q26_private.nominal_pair ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE lts_q26_private.nominal_pair FROM PUBLIC;
CREATE TABLE lts_q26_private.operation_receipt (
 operation_id uuid NOT NULL REFERENCES lts_q26_private.nominal_pair(operation_id),
 phase text NOT NULL CHECK(phase IN('apply','rollback')),
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 payload jsonb NOT NULL,
 PRIMARY KEY(operation_id,phase)
);
ALTER TABLE lts_q26_private.operation_receipt ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE lts_q26_private.operation_receipt FROM PUBLIC;
-- No client grants or policies are introduced. Existing trusted definer roles must be verified.
CREATE FUNCTION lts_q26_private.active_pair(p_user_id uuid)
RETURNS TABLE(operation_id uuid,user_id uuid,representative_id uuid,prior_id uuid,competence_month date,amount numeric,currency text,family text,representative_expected jsonb,prior_expected jsonb,invoice_expected jsonb,representative_expense_mask jsonb,prior_expense_mask jsonb,active boolean)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path TO '' AS $active$
 SELECT p.operation_id,p.user_id,p.representative_id,p.prior_id,p.competence_month,p.amount,p.currency,p.family,p.representative_expected,p.prior_expected,p.invoice_expected,p.representative_expense_mask,p.prior_expense_mask,p.active FROM lts_q26_private.nominal_pair p
 JOIN public.lts_open_finance_staging r ON r.user_id=p.user_id AND r.id=p.representative_id
 JOIN public.lts_open_finance_staging o ON o.user_id=p.user_id AND o.id=p.prior_id
 JOIN public.lts_open_finance_staging b ON b.user_id=p.user_id AND b.id=(p.invoice_expected->>'id')::uuid
 WHERE p.active AND p.user_id=p_user_id
 AND ((SELECT jsonb_object_agg(k,to_jsonb(r)->k) FROM unnest(ARRAY['id','user_id','provider','currency','posting_date','resource_type','signed_amount','institution_code','provider_record_id','provider_deleted_at','provider_account_ref']) k)||jsonb_build_object('raw_payload',(SELECT jsonb_object_agg(k,r.raw_payload->k) FROM unnest(ARRAY['id','date','type','amount','status','accountId','currencyCode']) k)||jsonb_build_object('creditCardMetadata',(SELECT jsonb_object_agg(k,(r.raw_payload->'creditCardMetadata')->k) FROM unnest(ARRAY['billId','cardNumber','billPostDate','purchaseDate','installmentNumber','totalInstallments','transactionDateTime']) k)),'normalized_payload',(SELECT jsonb_object_agg(k,r.normalized_payload->k) FROM unnest(ARRAY['date','last4','layer','amount','status','bill_id','currency','account_type','account_last4','provider_account_id','provider_id','provider_civil_date','installment_number','total_installments']) k)))=p.representative_expected
 AND ((SELECT jsonb_object_agg(k,to_jsonb(o)->k) FROM unnest(ARRAY['id','user_id','provider','currency','posting_date','resource_type','signed_amount','institution_code','provider_record_id','provider_deleted_at','provider_account_ref']) k)||jsonb_build_object('raw_payload',(SELECT jsonb_object_agg(k,o.raw_payload->k) FROM unnest(ARRAY['id','date','type','amount','status','accountId','currencyCode']) k)||jsonb_build_object('creditCardMetadata',(SELECT jsonb_object_agg(k,(o.raw_payload->'creditCardMetadata')->k) FROM unnest(ARRAY['billId','cardNumber','billPostDate','purchaseDate','installmentNumber','totalInstallments','transactionDateTime']) k)),'normalized_payload',(SELECT jsonb_object_agg(k,o.normalized_payload->k) FROM unnest(ARRAY['date','last4','layer','amount','status','bill_id','currency','account_type','account_last4','provider_account_id','provider_id','provider_civil_date','installment_number','total_installments']) k)))=p.prior_expected
 AND ((SELECT jsonb_object_agg(k,to_jsonb(b)->k) FROM unnest(ARRAY['id','user_id','provider','currency','resource_type','institution_code','provider_record_id','provider_deleted_at','provider_account_ref']) k)||jsonb_build_object('raw_payload',(SELECT jsonb_object_agg(k,b.raw_payload->k) FROM unnest(ARRAY['id','totalAmountCurrencyCode']) k)))=p.invoice_expected
 -- Both nominal source snapshots carry the different exact timestamps. No time tolerance.
 AND r.provider_deleted_at IS NULL AND o.provider_deleted_at IS NULL AND b.provider_deleted_at IS NULL
 AND r.normalized_payload->>'status'='POSTED' AND o.normalized_payload->>'status'='PENDING'
 AND r.raw_payload#>>'{creditCardMetadata,billId}'=b.raw_payload->>'id'
 AND o.raw_payload#>>'{creditCardMetadata,billId}' IS NULL
$active$;
REVOKE ALL ON FUNCTION lts_q26_private.active_pair(uuid) FROM PUBLIC;
CREATE FUNCTION lts_q26_private.resolve_card_detail(p_user_id uuid,p_family text,p_month date,p_result jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO '' AS $card$
DECLARE p record; r jsonb; o jsonb; items jsonb; before_total numeric; after_total numeric; n integer;
BEGIN
 SELECT * INTO p FROM lts_q26_private.active_pair(p_user_id)
 WHERE family=p_family AND competence_month=date_trunc('month',p_month)::date;
 IF NOT FOUND OR jsonb_typeof(p_result->'items') IS DISTINCT FROM 'array'
 OR coalesce((p_result->>'document_items_matched')::boolean,false) THEN RETURN p_result; END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(p_result->'items') x WHERE x->>'source_id'=p.representative_id::text)<>1
 OR (SELECT count(*) FROM jsonb_array_elements(p_result->'items') x WHERE x->>'source_id'=p.prior_id::text)<>1 THEN RETURN p_result; END IF;
 SELECT x INTO r FROM jsonb_array_elements(p_result->'items') x WHERE x->>'source_id'=p.representative_id::text;
 SELECT x INTO o FROM jsonb_array_elements(p_result->'items') x WHERE x->>'source_id'=p.prior_id::text;
 IF NOT (r @> jsonb_build_object('provider_status','POSTED','amount',p.amount,'reference_month',p.competence_month,
   'installment_number',2,'total_installments',3,'last4',p.representative_expected#>>'{raw_payload,creditCardMetadata,cardNumber}',
   'posting_date',p.representative_expected->>'posting_date','purchase_date',left(p.representative_expected#>>'{raw_payload,creditCardMetadata,purchaseDate}',10),'is_payment',false)
 AND o @> jsonb_build_object('provider_status','PENDING','amount',p.amount,'reference_month',p.competence_month,
   'installment_number',2,'total_installments',3,'last4',p.prior_expected#>>'{raw_payload,creditCardMetadata,cardNumber}',
   'posting_date',p.prior_expected->>'posting_date','purchase_date',left(p.prior_expected#>>'{raw_payload,creditCardMetadata,purchaseDate}',10),'is_payment',false)) THEN RETURN p_result; END IF;
 SELECT count(*),sum((x->>'amount')::numeric) INTO n,before_total FROM jsonb_array_elements(p_result->'items') x;
 IF (p_result->>'item_count')::integer IS DISTINCT FROM n OR (p_result->>'amount')::numeric IS DISTINCT FROM before_total
 OR (p_result ? 'detail_total' AND (p_result->>'detail_total')::numeric IS DISTINCT FROM before_total) THEN RETURN p_result; END IF;
 SELECT coalesce(jsonb_agg(x ORDER BY ord),'[]'::jsonb) INTO items
 FROM jsonb_array_elements(p_result->'items') WITH ORDINALITY a(x,ord) WHERE x->>'source_id' IS DISTINCT FROM p.prior_id::text;
 after_total:=before_total-p.amount;
 p_result:=p_result||jsonb_build_object('items',items,'amount',after_total,'item_count',n-1,
 'difference',CASE WHEN p_result->>'invoice_amount' IS NOT NULL THEN (p_result->>'invoice_amount')::numeric-after_total ELSE NULL END,
 'unclassified',(SELECT count(*) FROM jsonb_array_elements(items)x WHERE x->>'category_basis'='unresolved'),
 'categories',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.category),'[]'::jsonb) FROM (SELECT x->>'category' category,count(*) n,sum((x->>'amount')::numeric) amount FROM jsonb_array_elements(items)x GROUP BY 1)q),
 'instruments',(SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.last4),'[]'::jsonb) FROM (SELECT x->>'last4' last4,count(*) n,sum((x->>'amount')::numeric) amount FROM jsonb_array_elements(items)x GROUP BY 1)q),
 'reconciliation_provenance',jsonb_build_object('operation_id',p.operation_id,'basis','owner_approved_nominal_composite_identity',
 'representative_source_id',p.representative_id,'not_additional_expenses',true,'prior_observation',o));
 IF p_result ? 'detail_total' THEN p_result:=jsonb_set(p_result,'{detail_total}',to_jsonb(after_total)); END IF;
 RETURN p_result;
END $card$;
REVOKE ALL ON FUNCTION lts_q26_private.resolve_card_detail(uuid,text,date,jsonb) FROM PUBLIC;
CREATE FUNCTION public.fixture_expense_rows(p_user_id uuid) RETURNS SETOF public.fixture_expenses LANGUAGE sql STABLE SET search_path TO '' AS $fixture$ WITH economic_rows AS MATERIALIZED (SELECT * FROM public.fixture_expenses WHERE p_user_id='11111111-1111-4111-8111-111111111111'::uuid UNION ALL SELECT * FROM public.fixture_other_expenses WHERE p_user_id='66666666-6666-4666-8666-666666666666'::uuid), nominal_pairs AS MATERIALIZED (
 SELECT * FROM lts_q26_private.active_pair(p_user_id)
), excluded_observation AS MATERIALIZED (
 SELECT p.prior_id,p.competence_month FROM nominal_pairs p
 WHERE (SELECT count(*) FROM economic_rows e WHERE e.source_table='lts_open_finance_staging' AND e.source_ref=p.representative_id::text AND e.competence_month=p.competence_month)=1
 AND (SELECT count(*) FROM economic_rows e WHERE e.source_table='lts_open_finance_staging' AND e.source_ref=p.prior_id::text AND e.competence_month=p.competence_month)=1
 AND EXISTS(SELECT 1 FROM economic_rows e WHERE e.source_table='lts_open_finance_staging' AND e.source_ref=p.representative_id::text AND to_jsonb(e) @> p.representative_expense_mask)
 AND EXISTS(SELECT 1 FROM economic_rows e WHERE e.source_table='lts_open_finance_staging' AND e.source_ref=p.prior_id::text AND to_jsonb(e) @> p.prior_expense_mask)
)
SELECT e.* FROM economic_rows e
WHERE NOT EXISTS(SELECT 1 FROM excluded_observation x WHERE e.source_table='lts_open_finance_staging' AND e.source_ref=x.prior_id::text AND e.competence_month=x.competence_month)
$fixture$;
