CREATE TEMP TABLE fixture_card AS SELECT $data${"items":[{"source_id":"22222222-2222-4222-8222-222222222222","provider_status":"POSTED","amount":12.34,"reference_month":"2020-10-01","installment_number":2,"total_installments":3,"last4":"9900","posting_date":"2020-09-25","purchase_date":"2020-08-24","is_payment":false,"category":"Fixture shop","category_basis":"user_decision"},{"source_id":"33333333-3333-4333-8333-333333333333","provider_status":"PENDING","amount":12.34,"reference_month":"2020-10-01","installment_number":2,"total_installments":3,"last4":"9900","posting_date":"2020-09-25","purchase_date":"2020-08-24","is_payment":false,"category":"Fixture shop","category_basis":"user_decision"},{"source_id":"66666666-6666-4666-8666-666666666666","provider_status":"POSTED","amount":5.67,"reference_month":"2020-10-01","installment_number":2,"total_installments":3,"last4":"9900","posting_date":"2020-09-25","purchase_date":"2020-08-24","is_payment":false,"category":"Fixture shop","category_basis":"user_decision"}],"amount":30.35,"item_count":3,"invoice_amount":98.76,"difference":68.41,"basis":"fixture-chosen-composition","alternative_items":[{"source_id":"22222222-2222-4222-8222-222222222222","provider_status":"POSTED","amount":12.34,"reference_month":"2020-10-01","installment_number":2,"total_installments":3,"last4":"9900","posting_date":"2020-09-25","purchase_date":"2020-08-24","is_payment":false,"category":"Fixture shop","category_basis":"user_decision"},{"source_id":"33333333-3333-4333-8333-333333333333","provider_status":"PENDING","amount":12.34,"reference_month":"2020-10-01","installment_number":2,"total_installments":3,"last4":"9900","posting_date":"2020-09-25","purchase_date":"2020-08-24","is_payment":false,"category":"Fixture shop","category_basis":"user_decision"}],"financial_effect":"none"}$data$::jsonb value;
CREATE TEMP TABLE fixture_card_after AS SELECT lts_q26_private.resolve_card_detail('11111111-1111-4111-8111-111111111111','aeternum','2020-10-01',value) value FROM fixture_card;
SELECT public.fixture_assert((SELECT (value->>'amount')::numeric=18.01 AND (value->>'item_count')::int=2 FROM fixture_card_after),'card realizes one contribution');
SELECT public.fixture_assert((SELECT value->>'invoice_amount'='98.76' AND value->>'basis'='fixture-chosen-composition' FROM fixture_card_after),'card source choice and invoice intact');
