DELETE FROM public.fixture_expenses; INSERT INTO public.fixture_expenses SELECT * FROM fixture_original_rows;

DO $roles$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('service_role','anon','authenticated','q26_untrusted')) THEN RAISE EXCEPTION 'fresh disposable role namespace required'; END IF;
END $roles$;
CREATE ROLE service_role NOLOGIN NOSUPERUSER BYPASSRLS;
CREATE ROLE authenticated NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE ROLE anon NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE ROLE q26_untrusted NOLOGIN NOSUPERUSER NOBYPASSRLS;
GRANT USAGE ON SCHEMA public TO service_role,authenticated,anon,q26_untrusted;
GRANT SELECT ON public.lts_open_finance_staging,public.fixture_expenses,public.fixture_other_expenses TO service_role;
REVOKE ALL ON FUNCTION public.fixture_expense_rows(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fixture_expense_rows(uuid) TO service_role;
GRANT INSERT ON public.fixture_test_log TO service_role,authenticated,anon,q26_untrusted;
CREATE FUNCTION public.fixture_denied(stmt text,label text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER AS $deny$
DECLARE denied boolean:=false;
BEGIN
 BEGIN EXECUTE stmt; EXCEPTION WHEN insufficient_privilege THEN denied:=true; END;
 IF NOT denied THEN RAISE EXCEPTION 'expected permission denial: %',label; END IF;
 INSERT INTO public.fixture_test_log VALUES(label);
END $deny$;
SET LOCAL ROLE service_role;
SELECT public.fixture_denied('SELECT * FROM public.fixture_expense_rows(''11111111-1111-4111-8111-111111111111'')','BYPASSRLS alone does not grant private schema');
RESET ROLE;
-- HELD COMPONENT. Executed only inside the reviewed atomic envelope after all release gates.
-- Preserves an existing service_role invoker capability. No privilege inferred from BYPASSRLS.
DO $minimal_acl$
DECLARE c record; allowed constant text[]:=ARRAY['operation_id','user_id','representative_id','prior_id','competence_month','amount','currency','family','representative_expected','prior_expected','invoice_expected','representative_expense_mask','prior_expense_mask','active'];
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role' AND NOT rolsuper AND rolbypassrls)
 OR EXISTS(SELECT 1 FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member WHERE r.rolname='service_role') THEN RAISE EXCEPTION 'service_role privilege profile changed'; END IF;
 GRANT USAGE ON SCHEMA lts_q26_private TO service_role;
 GRANT EXECUTE ON FUNCTION lts_q26_private.active_pair(uuid) TO service_role;
 GRANT SELECT (operation_id,user_id,representative_id,prior_id,competence_month,amount,currency,family,representative_expected,prior_expected,invoice_expected,representative_expense_mask,prior_expense_mask,active) ON lts_q26_private.nominal_pair TO service_role;
 IF NOT has_schema_privilege('service_role','lts_q26_private','USAGE')
 OR NOT has_function_privilege('service_role','lts_q26_private.active_pair(uuid)','EXECUTE')
 OR has_schema_privilege('service_role','lts_q26_private','CREATE')
 OR has_table_privilege('service_role','lts_q26_private.nominal_pair','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
 OR has_table_privilege('service_role','lts_q26_private.operation_receipt','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') THEN RAISE EXCEPTION 'minimal ACL shape mismatch'; END IF;
 FOR c IN SELECT attname FROM pg_attribute WHERE attrelid='lts_q26_private.nominal_pair'::regclass AND attnum>0 AND NOT attisdropped LOOP
  IF has_column_privilege('service_role','lts_q26_private.nominal_pair',c.attname,'SELECT') IS DISTINCT FROM (c.attname=ANY(allowed))
  OR has_column_privilege('service_role','lts_q26_private.nominal_pair',c.attname,'INSERT,UPDATE,REFERENCES') THEN RAISE EXCEPTION 'column ACL scope mismatch: %',c.attname; END IF;
 END LOOP;
 FOR c IN SELECT p.oid,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='lts_q26_private' LOOP
  IF has_function_privilege('service_role',c.oid,'EXECUTE') IS DISTINCT FROM (c.oid='lts_q26_private.active_pair(uuid)'::regprocedure::oid) THEN RAISE EXCEPTION 'helper ACL scope mismatch: %',c.proname; END IF;
 END LOOP;
 FOR c IN SELECT rolname FROM pg_roles WHERE rolname IN('anon','authenticated') LOOP
  IF has_schema_privilege(c.rolname,'lts_q26_private','USAGE') OR has_function_privilege(c.rolname,'lts_q26_private.active_pair(uuid)','EXECUTE') THEN RAISE EXCEPTION 'unintended client access'; END IF;
 END LOOP;
END $minimal_acl$;

SET LOCAL ROLE service_role;
SELECT public.fixture_assert((SELECT count(*) FROM public.fixture_expense_rows('11111111-1111-4111-8111-111111111111'))=2,'service role existing invoker path preserved');
SELECT public.fixture_assert((SELECT count(*) FROM public.fixture_expense_rows('66666666-6666-4666-8666-666666666666'))=1 AND NOT EXISTS(SELECT 1 FROM public.fixture_expense_rows('66666666-6666-4666-8666-666666666666') WHERE source_ref IN('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333')),'other owner original rows preserved without pair exposure');
SELECT public.fixture_assert((SELECT NOT rolsuper AND rolbypassrls FROM pg_roles WHERE rolname=current_user),'service role tested without superuser');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','operation_id','SELECT'),'allowed column operation_id');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','user_id','SELECT'),'allowed column user_id');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','representative_id','SELECT'),'allowed column representative_id');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','prior_id','SELECT'),'allowed column prior_id');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','competence_month','SELECT'),'allowed column competence_month');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','amount','SELECT'),'allowed column amount');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','currency','SELECT'),'allowed column currency');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','family','SELECT'),'allowed column family');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','representative_expected','SELECT'),'allowed column representative_expected');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','prior_expected','SELECT'),'allowed column prior_expected');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','invoice_expected','SELECT'),'allowed column invoice_expected');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','representative_expense_mask','SELECT'),'allowed column representative_expense_mask');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','prior_expense_mask','SELECT'),'allowed column prior_expense_mask');
SELECT public.fixture_assert(has_column_privilege(current_user,'lts_q26_private.nominal_pair','active','SELECT'),'allowed column active');
SELECT public.fixture_assert(NOT has_table_privilege(current_user,'lts_q26_private.nominal_pair','SELECT'),'whole table select not granted');
SELECT public.fixture_denied($stmt$SELECT * FROM lts_q26_private.nominal_pair$stmt$,'SELECT star denied');
SELECT public.fixture_denied($stmt$SELECT approval FROM lts_q26_private.nominal_pair$stmt$,'private approval denied');
SELECT public.fixture_denied($stmt$SELECT decision_lineage FROM lts_q26_private.nominal_pair$stmt$,'private lineage denied');
SELECT public.fixture_denied($stmt$SELECT * FROM lts_q26_private.operation_receipt$stmt$,'private receipts denied');
SELECT public.fixture_denied($stmt$INSERT INTO lts_q26_private.operation_receipt SELECT * FROM lts_q26_private.operation_receipt$stmt$,'private insert denied');
SELECT public.fixture_denied($stmt$UPDATE lts_q26_private.nominal_pair SET active=active$stmt$,'private update denied');
SELECT public.fixture_denied($stmt$DELETE FROM lts_q26_private.nominal_pair$stmt$,'private delete denied');
SELECT public.fixture_denied($stmt$TRUNCATE lts_q26_private.operation_receipt$stmt$,'private truncate denied');
SELECT public.fixture_denied($stmt$CREATE TABLE lts_q26_private.unwanted(id int)$stmt$,'private schema create denied');
SELECT public.fixture_denied($stmt$SELECT lts_q26_private.resolve_card_detail('11111111-1111-4111-8111-111111111111','aeternum','2020-10-01','{}')$stmt$,'other helper execute denied');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT public.fixture_denied('SELECT * FROM lts_q26_private.active_pair(''11111111-1111-4111-8111-111111111111'')','authenticated has no direct private helper');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT public.fixture_denied('SELECT * FROM lts_q26_private.active_pair(''11111111-1111-4111-8111-111111111111'')','anon has no direct private helper');
RESET ROLE;
SET LOCAL ROLE q26_untrusted;
SELECT public.fixture_denied('SELECT * FROM lts_q26_private.active_pair(''11111111-1111-4111-8111-111111111111'')','q26_untrusted has no direct private helper');
RESET ROLE;
CREATE TEMP TABLE fixture_acl_applied AS SELECT attname,attacl FROM pg_attribute WHERE attrelid='lts_q26_private.nominal_pair'::regclass AND attnum>0 AND NOT attisdropped;
GRANT SELECT(approval) ON lts_q26_private.nominal_pair TO service_role;
SELECT public.fixture_assert(EXISTS(SELECT 1 FROM pg_attribute a JOIN fixture_acl_applied b ON b.attname=a.attname WHERE a.attrelid='lts_q26_private.nominal_pair'::regclass AND a.attacl IS DISTINCT FROM b.attacl),'later column ACL drift detected before compensation');
REVOKE SELECT(approval) ON lts_q26_private.nominal_pair FROM service_role;
-- Run only AFTER exact applied schema/relacl/attacl/function CAS and old consumer restoration.
-- A later grant or column permission change aborts at the envelope CAS, before any revoke.
REVOKE SELECT (operation_id,user_id,representative_id,prior_id,competence_month,amount,currency,family,representative_expected,prior_expected,invoice_expected,representative_expense_mask,prior_expense_mask,active) ON lts_q26_private.nominal_pair FROM service_role;
REVOKE EXECUTE ON FUNCTION lts_q26_private.active_pair(uuid) FROM service_role;
REVOKE USAGE ON SCHEMA lts_q26_private FROM service_role;
DO $verify_acl_reversal$
BEGIN
 IF has_schema_privilege('service_role','lts_q26_private','USAGE') OR has_function_privilege('service_role','lts_q26_private.active_pair(uuid)','EXECUTE')
 OR EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid='lts_q26_private.nominal_pair'::regclass AND a.attnum>0 AND NOT a.attisdropped AND has_column_privilege('service_role',a.attrelid,a.attnum,'SELECT')) THEN RAISE EXCEPTION 'minimal ACL compensation incomplete'; END IF;
END $verify_acl_reversal$;

SELECT public.fixture_assert(NOT has_schema_privilege('service_role','lts_q26_private','USAGE') AND NOT has_function_privilege('service_role','lts_q26_private.active_pair(uuid)','EXECUTE'),'exact proposed grants compensable without public ACL change');
UPDATE lts_q26_private.nominal_pair SET active=false,revoked_at='2020-10-16' WHERE operation_id='55555555-5555-4555-8555-555555555555';
SELECT public.fixture_assert((SELECT count(*) FROM public.fixture_expense_rows('11111111-1111-4111-8111-111111111111'))=3,'nominal revocation restores contribution');
SELECT public.fixture_assert((SELECT count(*) FROM public.lts_open_finance_staging WHERE id IN('22222222-2222-4222-8222-222222222222','33333333-3333-4333-8333-333333333333'))=2,'revocation preserves both sources');
SELECT jsonb_build_object('synthetic_checks_passed',count(*),'labels',jsonb_agg(label ORDER BY label)) AS synthetic_result FROM public.fixture_test_log;
ROLLBACK;
